    { "id": "bp23", "story": "Shaharda daraxtlarni shafqatsizlarcha (faqat tanasini qoldirib) butashdi. Yoz faslida shahar ichida nafas olish og'irlashdi.", "question": "Daraxt barglarining qanday xususiyati yo'qotildi?", "options": ["Changni tutib qolish va kislorod ishlab chiqarish xususiyati", "Shamolni to'xtatish xususiyati", "Manzarali ko'rinishi"], "answer_index": 0, "explanation": "To'g'ri! Barglar havoni tozalovchi \"o'pka\"dir, ularni asossiz kesish shaharni dim va chang qilib yuboradi." },
    { "id": "bp24", "story": "Bir hovuzda juda ko'p baliq boqilardi. Bahorda hovuz suviga qishloq xo'jaligi dalasidan o'g'itli suv kelib tushdi. Suvo'tlar shu qadar ko'paydiki, hovuz yashil rangga kirdi.", "question": "Hovuzdagi baliqlarga nima xavf soladi?", "options": ["Zaharli o'tlar", "Kechasi suvo'tlar kislorodni yutishi sababli baliqlar bo'g'ilib o'ladi (Evtrofikatsiya)", "Baliqlar suvo'tni yeb juda kattalashib ketadi"], "answer_index": 1, "explanation": "To'g'ri! Garchi o'simliklar kunduzi kislorod chiqarsa-da, juda ko'p miqdordagi suvo'tlar chiriganda va tunda suvda kislorod qolmaydi." },
    { "id": "bp25", "story": "Zavod yaqinidagi qishloq aholisi doimiy ravishda tish emalining yemirilishi va suyaklar mo'rtlashishidan (flyuoroz) shikoyat qila boshladi.", "question": "Zavod havoga asosan qaysi moddani chiqarmoqda?", "options": ["Azot", "Ftor birikmalari", "Metan"], "answer_index": 1, "explanation": "To'g'ri! Ftorning havo va suvda ko'payishi inson suyaklari va tishlarida og'ir kasalliklarni (flyuoroz) keltirib chiqaradi." },
    { "id": "bp26", "story": "Arktikada (Shimoliy qutb) havo harorati ko'tarilib muzliklar eriy boshladi.", "question": "Buning butun dunyoga ta'siri qanday bo'ladi?", "options": ["Faqat Arktikada havo isitadi", "Dunyo okeani sathi ko'tarilib, ko'plab orollar va qirg'oq shaharlari suv ostida qoladi", "Ekotizim o'zgarmaydi"], "answer_index": 1, "explanation": "To'g'ri! Global isish oqibatida muzliklarning erishi butun insoniyat uchun jiddiy ofatdir." },
    { "id": "bp27", "story": "Bir orolda ilonlarni yo'q qilishdi. Keyin kalamushlar shu qadar ko'paydiki, ular barcha qush uyalaridagi tuxumlarni yeb bitirdi.", "question": "Bu vaziyat nimani isbotlaydi?", "options": ["Ilonlar qushlarni qutqaruvchi bo'lgan", "Tabiatdagi oziq zanjirining bir halqasini uzib tashlash butun ekotizim halokatiga olib keladi", "Qushlar yashirinishni bilmaydi"], "answer_index": 1, "explanation": "To'g'ri! Tabiatda \"ortiqcha\" yoki \"keraksiz\" jonzot yo'q, barchasi muvozanatni saqlab turadi." },
    { "id": "bp28", "story": "Plastik idishlarni tashlab yubormasdan, ularni isitib, presslab, yangi qurilish materiallari ishlab chiqarila boshlandi.", "question": "Bu qanday usul hisoblanadi?", "options": ["Reutilizatsiya (Qayta ishlash)", "Konservatsiya", "Tabiatni ifloslantirish"], "answer_index": 0, "explanation": "To'g'ri! Plastikdan yangi materiallar (masalan, ekocherepitsa yoki trubalar) yasash eng toza qayta ishlash usulidir." },
    { "id": "bp29", "story": "O'rmon yong'inidan so'ng u yerdagi kul va qora kuygan daraxtlar o'rnida birinchi bo'lib mayda o'tlar va moxlar o'sib chiqdi. 10 yildan so'ng butalar, 50 yildan so'ng yana o'rmon tiklandi.", "question": "Ushbu ketma-ketlik biologiyada qanday nomlanadi?", "options": ["Ikkilamchi suksessiya", "Eroziya", "Degradatsiya"], "answer_index": 0, "explanation": "To'g'ri! Buzilgan ekotizimning (yong'in yoki kesishdan keyin) asta-sekin, bosqichma-bosqich o'zini o'zi tiklashi ikkilamchi suksessiya deyiladi." },
    { "id": "bp30", "story": "Tog'li hududda o'sadigan noyob lolani odamlar tomorqasiga ekish uchun piyozchasi (tomiri) bilan yulib kela boshlashdi.", "question": "Lola populyatsiyasiga qanday ta'sir ko'rsatiladi?", "options": ["U boshqa joyda ko'payadi", "Piyozchasi bilan yulingan noyob o'simlik tabiatda boshqa o'smaydi va butunlay qirilib ketadi", "Havo tozalanadi"], "answer_index": 1, "explanation": "To'g'ri! Nodir o'simliklarni (ayniqsa piyozchali turlarni) tabiatdan yulib olish qat'iyan man etiladi, chunki ular faqat o'zining tabiiy biotopida yashay oladi." },
    { "id": "bp31", "story": "Odamlar shaharda chiroyli ko'rinishi uchun chet eldan keltirilgan, tez o'sadigan begona daraxt turini ommaviy ekishdi. Bu daraxt mahalliy qurt-qumursqalarni yo'q qilib, boshqa daraxtlarni siqib chiqardi.", "question": "Bu begona daraxt ekologiyada qanday nomlanadi?", "options": ["Noyob tur", "Invaziv (bosqinchi) tur", "Endemik tur"], "answer_index": 1, "explanation": "To'g'ri! Boshqa hududdan keltirilgan va mahalliy ekotizimga tajovuz qilib muvozanatni buzuvchi turlar invaziv turlar deyiladi." },
    { "id": "bp32", "story": "Fermer dala chetlariga daraxtlardan iborat ihota (to'siq) o'rmon mintaqasini ekdi.", "question": "Buning dalaga foydasi bormi?", "options": ["Foydasi yo'q, joyni egallaydi", "Ha, u ekinlarni kuchli shamoldan, tuproqni eroziyadan asraydi va namlikni saqlaydi", "Faqat qushlarga foyda"], "answer_index": 1, "explanation": "To'g'ri! Ihota o'rmonlari mikroklimatni yaxshilaydi, tuproqni uchib ketishdan saqlab qoladi." },
    { "id": "bp33", "story": "Zavod ishlab chiqarish jarayonida hosil bo'lgan chiqindi gazlarni atmosferaga chiqarish o'rniga, undan issiqlik energiyasi oldi.", "question": "Bu qanday texnologiya?", "options": ["Eski usul", "Chiqindisiz (yoki kam chiqindili) energiya tejamkor texnologiya", "Ifloslantiruvchi texnologiya"], "answer_index": 1, "explanation": "To'g'ri! Resurslarni maksimal tejaydigan bunday texnologiyalar ekologiyaning zamonaviy talabidir." },
    { "id": "bp34", "story": "Qishloqda yer osti ichimlik suvi quduqlari sho'rlanib, ta'mi ayniydi.", "question": "Bunga nima sabab bo'lishi mumkin?", "options": ["Quduqning eski ekani", "Yaqin atrofdagi maishiy chiqindi poligonlaridan yomg'ir suvi orqali zaharli moddalarning yer osti suviga sızib tushishi", "Quyosh nuri"], "answer_index": 1, "explanation": "To'g'ri! Noto'g'ri qurilgan axlatxonalar va o'g'it omborlaridan sizib chiqqan zahar yer osti suvlarini (sizot suvlarini) ifloslantiradi." },
    { "id": "bp35", "story": "Tadbirkor o'z hovlisidagi chuqurga barcha plastik va rezina chiqindilarni to'plab, yoqib yubordi. U axlatxona pulini tejab qoldim deb o'yladi.", "question": "Uning hatti-harakati qanday oqibatga olib keladi?", "options": ["Atrof muhit tozalanadi", "Yonish jarayonida ajralgan zaharli dioksin va furanlar o'zi va qo'shnilarining sog'lig'iga halokatli ta'sir qiladi", "Hech qanday oqibati yo'q"], "answer_index": 1, "explanation": "To'g'ri! Rezina va plastikni ochiq yoqish saratonga sabab bo'luvchi eng o'ta zaharli moddalarni (dioksin) havoga tarqatadi." },
    { "id": "bp36", "story": "Okeanlarda ohaktosh va marjon qoyalari (riflari) oqarib, nobud bo'lmoqda.", "question": "Buning asosiy sababi nima deb hisoblanadi?", "options": ["Baliqlar yeb qo'ymoqda", "Okean suvining isishi va uning kislotaliligi (CO2 hisobiga) ortishi", "Kemalar harakati"], "answer_index": 1, "explanation": "To'g'ri! Karbonat angidrid suvda erib kislota hosil qiladi, bu esa nozik marjonlarni nobud qiladi." },
    { "id": "bp37", "story": "Ko'chada eskirgan batareyka (tok manbai) yotibdi, bir bola uni tuproqqa ko'mib tashladi.", "question": "Kichkina batareyka tabiatga zarar qiladimi?", "options": ["Yo'q, u juda kichkina", "Ha, bitta kichik batareyka tuproqdagi og'ir metallar (qo'rg'oshin, simob, kadmiy) tufayli 20 kvadrat metr yerni va yuzlab litr suvni zaharli qiladi", "U chirib o'g'it bo'ladi"], "answer_index": 1, "explanation": "To'g'ri! Batareykalar oddiy axlat emas, ular o'ta xavfli qoldiq hisoblanadi va maxsus joylarga topshirilishi shart." },
    { "id": "bp38", "story": "Cho'pon o'zining yuzlab qo'ylarini har yili bahorda aynan bitta hududda boqaverdi.", "question": "Yillar o'tib bu hudud qanday holatga tushadi?", "options": ["O'tlar ko'payadi", "Yerdagi o'simliklar o'sishga ulgurmaydi, tuproq tepkilanib eroziyaga uchraydi va joy cho'lga aylanadi (Degradatsiya)", "O'rmon paydo bo'ladi"], "answer_index": 1, "explanation": "To'g'ri! Yaylovlardan nazoratsiz va tizimsiz foydalanish ularning degradatsiyasiga olib keladi." },
    { "id": "bp39", "story": "Ovchi davlat tomonidan ruxsat etilgan vaqtda (kuzda) va qoidaga muvofiq bitta yovvoyi o'rdakni ovladi.", "question": "U qonunni buzdimi?", "options": ["Ha, ov mutlaqo taqiqlangan", "Yo'q, agar u tegishli ruxsatnoma olgan bo'lsa va otish normasi doirasida bo'lsa, bu qonuniy (havaskor) ov hisoblanadi", "Ha, faqat qishda mumkin"], "answer_index": 1, "explanation": "To'g'ri! Qonun hujjatlari asosida, ma'lum davrlarda ruxsatnoma (putyovka) bilan ov qilish mumkin." },
    { "id": "bp40", "story": "Mamlakatda \"Yashil makon\" dasturi asosida har yili millionlab daraxtlar ekilmoqda.", "question": "Buning asosiy maqsadi nima?", "options": ["O'tin zaxirasini ko'paytirish", "Iqlim mo'tadilligini ta'minlash, kislorod manbaini ko'paytirish va chang bo'ronlarining oldini olish", "Shahar maydonlarini to'ldirish"], "answer_index": 1, "explanation": "To'g'ri! Ommaviy ko'kalamzorlashtirish ekologik muammolarni hal etishning eng samarali va amaliy usulidir." }
]
