    { "id": "btf39", "question": "O'zbekistonda Amudaryo va Sirdaryo sirkulasiyasi Orol dengizining holatiga bevosita bog'liq.", "options": ["Rost", "Yolg'on"], "answer_index": 0, "explanation": "Rost! Orol dengizi asosan aynan shu ikkita buyuk daryo suvi hisobiga to'yinar edi." },
